22	function deriveTaskTitleFromSpec(spec: string): string {
23	  for (const line of spec.split(/\r?\n/)) {
24	    const title = normalizeSingleLine(line, ORCHESTRATION_TASK_TITLE_MAX_LENGTH)
25	    if (title) {
26	      return title
27	    }
28	  }
29	  return normalizeSingleLine(spec, ORCHESTRATION_TASK_TITLE_MAX_LENGTH)
30	}
