 47	export function readOrchestrationCompatibilityEvidence(
 48	  env: Readonly<Record<string, string | undefined>>
 49	): OrchestrationCompatibilityEvidence | undefined {
 50	  const terminalHandle = boundedValue(env.ORCA_TERMINAL_HANDLE)
 51	  const paneKey = boundedValue(env.ORCA_PANE_KEY)
 52	  const launchToken = boundedValue(env.ORCA_AGENT_LAUNCH_TOKEN)
 53	  const host = readHostStamp(env)
 54	  if (!terminalHandle && !paneKey && !launchToken && !host) {
 55	    return undefined
 56	  }
 57	  return {
 58	    ...(terminalHandle ? { terminalHandle } : {}),
 59	    ...(paneKey ? { paneKey } : {}),
 60	    ...(launchToken ? { launchToken } : {}),
 61	    ...(host ? { host } : {})
 62	  }
 63	}
