 65	function readHostStamp(
 66	  env: Readonly<Record<string, string | undefined>>
 67	): OrchestrationCompatibilityHostStamp | undefined {
 68	  const kind = boundedValue(env[ORCHESTRATION_COMPATIBILITY_HOST_KIND_ENV])
 69	  const hostId = boundedValue(env[ORCHESTRATION_COMPATIBILITY_HOST_ID_ENV])
 70	  const incarnation = boundedValue(env[ORCHESTRATION_COMPATIBILITY_HOST_INCARNATION_ENV])
 71	  const attachment = boundedValue(env[ORCHESTRATION_COMPATIBILITY_ATTACHMENT_ENV])
 72	  if (kind === 'wsl' && hostId && incarnation) {
 73	    return { kind, hostId, distro: incarnation }
 74	  }
 75	  if (kind === 'ssh' && hostId && incarnation && attachment) {
 76	    return {
